#!/usr/bin/env node
/**
 * delete-wave-insight-stubs — remove the content-free "X — Insight" satellites
 * that wave 4 created, one per generated insight document.
 *
 * WHAT THESE ARE. wave-controller's wave-4 block wrote an Insight-classed node
 * per document whose entire content is boilerplate:
 *
 *     Insight document generated by wave-analysis for Foo (Detail).
 *     Source document: /…/knowledge-management/insights/Foo.md
 *
 * 128 of them on 2026-09-20, every single one that exact shape (153-244 chars).
 * Meanwhile the document itself holds ~9KB of real analysis and the REAL entity
 * — one hop in, e.g. `LslSessionDurationCache` — already carries both the
 * genuine description AND `has_insight_document` / `validated_file_path`
 * pointing at that document. The satellite adds a filename and nothing else.
 *
 * WHY IT EXISTED. HistorySidebar filters to `entityType === 'Insight'`, and
 * UKB writes Components/SubComponents/Details. Rather than widen the filter,
 * the wave manufactured nodes of the class the sidebar wanted — fitting the
 * knowledge base to a view. The filter is being widened instead; these go.
 *
 * SAFETY. There are ~900 legitimate online-learned Insight entities in this
 * graph. Deleting by entityType alone would destroy them, so a row must match
 * ALL THREE of:
 *   1. entityType === 'Insight'
 *   2. metadata.source === 'wave-analysis'
 *   3. description starts with the exact boilerplate prefix
 * Anything failing any one of them is left alone and counted.
 *
 * Usage:
 *   node scripts/delete-wave-insight-stubs.mjs            # dry run (default)
 *   node scripts/delete-wave-insight-stubs.mjs --apply    # delete
 */

const OBS_API = process.env.OBS_API_URL || 'http://localhost:12436';
const APPLY = process.argv.includes('--apply');
const PREFIX = 'Insight document generated by wave-analysis for';

const out = (m = '') => process.stdout.write(`${m}\n`);

const get = async (p) => {
  const r = await fetch(`${OBS_API}${p}`, { signal: AbortSignal.timeout(300_000) });
  if (!r.ok) throw new Error(`GET ${p} -> ${r.status}`);
  return (await r.json()).data;
};

if (APPLY) {
  try {
    const st = await get('/api/workflows/wave-analysis/status');
    if (st?.running) {
      out('REFUSING to apply: a wave-analysis run is in flight (it would recreate these).');
      process.exit(2);
    }
  } catch {
    out('WARNING: could not read wave-analysis status; proceeding.');
  }
}

const entities = await get('/api/v1/entities?limit=20000');

const insights = entities.filter((e) => e.entityType === 'Insight');
const stubs = [];
const spared = { wrongSource: 0, realContent: 0 };

for (const e of insights) {
  const md = e.metadata ?? {};
  if (md.source !== 'wave-analysis') { spared.wrongSource += 1; continue; }
  if (!String(e.description ?? '').startsWith(PREFIX)) { spared.realContent += 1; continue; }
  stubs.push(e);
}

out(`Insight entities in graph          : ${insights.length}`);
out(`  stubs to delete (all 3 guards)   : ${stubs.length}`);
out(`  spared — not wave-analysis       : ${spared.wrongSource}`);
out(`  spared — has real content        : ${spared.realContent}`);
out('');

if (stubs.length === 0) { out('Nothing to do.'); process.exit(0); }

for (const e of stubs.slice(0, 5)) out(`  ${APPLY ? 'delete' : 'would delete'}  ${e.name}`);
if (stubs.length > 5) out(`  … and ${stubs.length - 5} more`);
out('');

if (!APPLY) { out('Dry run. Re-run with --apply.'); process.exit(0); }

let deleted = 0;
let failed = 0;
for (const e of stubs) {
  const r = await fetch(`${OBS_API}/api/v1/entities/${encodeURIComponent(e.id)}`, {
    method: 'DELETE',
    signal: AbortSignal.timeout(60_000),
  });
  if (!r.ok) {
    if (failed < 3) out(`  FAILED ${e.name} -> ${r.status} ${(await r.text()).slice(0, 120)}`);
    failed += 1;
    continue;
  }
  deleted += 1;
}

out(`deleted: ${deleted}${failed ? `, failed: ${failed}` : ''}`);
const stats = await get('/api/v1/stats');
out(`nodes now: ${stats.nodeCount}, edges: ${stats.edgeCount}`);
